G=[[8,8,6],[6,3,6],[6,8,8]]
def fv(m): return m[::-1]
def fh(m): return [r[::-1] for r in m]
out=[]
for bi in range(3):
    for r in range(3):
        row=[]
        for bj in range(3):
            b=[c[:] for c in G]
            if bi!=1: b=fv(b)
            if bj!=1: b=fh(b)
            row+=b[r]
        out.append(row)
for r in out: print(r)
